```

## 二、核心玩法实现

### 2.1 游戏主循环 (src/core/Game.js)
```javascript
class Game {
  constructor(canvas) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d');
    this.lastTime = 0;
    this.deltaTime = 0;
    this.isRunning = false;
    this.entities = [];
    this.systems = [];

    // 性能监控
    this.performance = new PerformanceMonitor();
    this.fps = 0;
    this.frameCount = 0;
    this.lastFpsUpdate = 0;
  }

  start() {
    this.isRunning = true;
    this.lastTime = performance.now();
    this.gameLoop();
  }

  gameLoop(currentTime = 0) {
    if (!this.isRunning) return;

    this.deltaTime = (currentTime - this.lastTime) / 1000;
    this.lastTime = currentTime;

    // 更新FPS
    this.frameCount++;
    if (currentTime - this.lastFpsUpdate >= 1000) {
      this.fps = this.frameCount;
      this.frameCount = 0;
      this.lastFpsUpdate = currentTime;
    }

    this.update(this.deltaTime);
    this.render();

    requestAnimationFrame((time) => this.gameLoop(time));
  }

  update(dt) {
    // 更新所有系统
    this.systems.forEach(system => system.update(dt));

    // 更新所有实体
    this.entities.forEach(entity => entity.update(dt));

    // 清理已销毁的实体
    this.entities = this.entities.filter(entity => !entity.destroyed);
  }

  render() {
    // 清空画布
    this.ctx.fillStyle = '#000011';
    this.ctx.fillRect(0, 0, this.canvas.width, this.canvas.height);

    // 渲染所有系统
    this.systems.forEach(system => system.render(this.ctx));

    // 渲染所有实体
    this.entities.forEach(entity => entity.render(this.ctx));

    // 渲染UI
    this.renderUI();
  }

  renderUI() {
    this.ctx.fillStyle = '#ffffff';
    this.ctx.font = '16px Arial';
    this.ctx.fillText(`FPS: ${this.fps}`, 10, 20);
    this.ctx.fillText(`Entities: ${this.entities.length}`, 10, 40);
  }
}
```

### 2.2 玩家飞机 (src/entities/Player.js)
```javascript
class Player extends Entity {
  constructor(x, y) {
    super(x, y);
    this.width = 40;
    this.height = 40;
    this.speed = 300;
    this.health = 100;
    this.fireRate = 0.2;
    this.lastFireTime = 0;
    this.invulnerable = false;
    this.invulnerableTime = 0;

    // 输入状态
    this.keys = {};
    this.setupInput();
  }

  setupInput() {
    window.addEventListener('keydown', (e) => {
      this.keys[e.key] = true;
    });

    window.addEventListener('keyup', (e) => {
      this.keys[e.key] = false;
    });
  }

  update(dt) {
    // 移动控制
    if (this.keys['ArrowLeft'] || this.keys['a']) {
      this.x -= this.speed * dt;
    }
    if (this.keys['ArrowRight'] || this.keys['d']) {
      this.x += this.speed * dt;
    }
    if (this.keys['ArrowUp'] || this.keys['w']) {
      this.y -= this.speed * dt;
    }
    if (this.keys['ArrowDown'] || this.keys['s']) {
      this.y += this.speed * dt;
    }

    // 边界限制
    this.x = Math.max(0, Math.min(this.canvas.width - this.width, this.x));
    this.y = Math.max(0, Math.min(this.canvas.height - this.height, this.y));

    // 射击
    if (this.keys[' '] && performance.now() - this.lastFireTime > this.fireRate * 1000) {
      this.fire();
      this.lastFireTime = performance.now();
    }

    // 无敌时间
    if (this.invulnerable) {
      this.invulnerableTime -= dt;
      if (this.invulnerableTime <= 0) {
        this.invulnerable = false;
      }
    }
  }

  fire() {
    const bullet = new Bullet(this.x + this.width/2, this.y);
    this.game.addEntity(bullet);
  }

  render(ctx) {
    ctx.save();

    // 无敌闪烁效果
    if (this.invulnerable && Math.floor(Date.now() / 100) % 2 === 0) {
      ctx.globalAlpha = 0.5;
    }

    // 绘制飞机
    ctx.fillStyle = '#00ff88';
    ctx.beginPath();
    ctx.moveTo(this.x + this.width/2, this.y);
    ctx.lineTo(this.x, this.y + this.height);
    ctx.lineTo(this.x + this.width, this.y + this.height);
    ctx.closePath();
    ctx.fill();

    // 引擎火焰
    ctx.fillStyle = '#ff6600';
    ctx.fillRect(this.x + this.width/2 - 3, this.y + this.height, 6, 10);

    ctx.restore();
  }
}
```

### 2.3 敌机系统 (src/entities/Enemy.js)
```javascript
class Enemy extends Entity {
  constructor(x, y, type = 'basic') {
    super(x, y);
    this.type = type;
    this.setupByType();
    this.direction = Math.random() > 0.5 ? 1 : -1;
    this.shootTimer = Math.random() * 2;
  }

  setupByType() {
    switch(this.type) {
      case 'basic':
        this.width = 30;
        this.height = 30;
        this.speed = 100;
        this.health = 1;
        this.score = 10;
        break;
      case 'fast':
        this.width = 25;
        this.height = 25;
        this.speed = 200;
        this.health = 1;
        this.score = 15;
        break;
      case 'tank':
        this.width = 40;
        this.height = 40;
        this.speed = 50;
        this.health = 3;
        this.score = 30;
        break;
    }
  }

  update(dt) {
    // 移动模式
    this.y += this.speed * dt;
    this.x += Math.sin(this.y * 0.01) * this.direction * 50 * dt;

    // 边界检查
    if (this.y > this.canvas.height + this.height) {
      this.destroy();
    }

    // 射击
    this.shootTimer -= dt;
    if (this.shootTimer <= 0) {
      this.shoot();
      this.shootTimer = 1 + Math.random() * 2;
    }
  }

  shoot() {
    const bullet = new EnemyBullet(this.x + this.width/2, this.y + this.height);
    this.game.addEntity(bullet);
  }

  render(ctx) {
    ctx.fillStyle = this.getColor();
    ctx.fillRect(this.x, this.y, this.width, this.height);

    // 敌机细节
    ctx.fillStyle = '#ff0000';
    ctx.fillRect(this.x + this.width/4, this.y + this.height/4, 
                 this.width/2, this.height/2);
  }

  getColor() {
    switch(this.type) {
      case 'basic': return '#ff4444';
      case 'fast': return '#ffaa00';
      case 'tank': return '#aa44ff';
      default: return '#ff4444';
    }
  }
}
```

### 2.4 碰撞检测系统 (src/systems/Collision.js)
```javascript
class CollisionSystem {
  constructor(game) {
    this.game = game;
  }

  update(dt) {
    const entities = this.game.entities;
    const bullets = entities.filter(e => e instanceof Bullet);
    const enemies = entities.filter(e => e instanceof Enemy);
    const player = entities.find(e => e instanceof Player);

    // 子弹与敌机碰撞
    bullets.forEach(bullet => {
      enemies.forEach(enemy => {
        if (this.checkCollision(bullet, enemy)) {
          enemy.health--;
          bullet.destroy();

          if (enemy.health <= 0) {
            enemy.destroy();
            this.game.score += enemy.score;
            this.createExplosion(enemy.x, enemy.y);
          }
        }
      });
    });

    // 玩家与敌机碰撞
    if (player && !player.invulnerable) {
      enemies.forEach(enemy => {
        if (this.checkCollision(player, enemy)) {
          player.health -= 20;
          enemy.destroy();
          this.createExplosion(enemy.x, enemy.y);

          if (player.health <= 0) {
            this.game.gameOver();
          } else {
            player.invulnerable = true;
            player.invulnerableTime = 2;
          }
        }
      });
    }
  }

  checkCollision(a, b) {
    return a.x < b.x + b.width &&
           a.x + a.width > b.x &&
           a.y < b.y + b.height &&
           a.y + a.height > b.y;
  }

  createExplosion(x, y) {
    const particles = new ParticleSystem(x, y, 10);
    this.game.addSystem(particles);
  }
}
```

## 三、性能优化实现

### 3.1 对象池系统 (src/utils/ObjectPool.js)
```javascript
class ObjectPool {
  constructor(createFn, resetFn, initialSize = 10) {
    this.createFn = createFn;
    this.resetFn = resetFn;
    this.pool = [];

    // 预创建对象
    for (let i = 0; i < initialSize; i++) {
      this.pool.push(this.createFn());
    }
  }

  get() {
    if (this.pool.length > 0) {
      return this.pool.pop();
    }
    return this.createFn();
  }

  release(obj) {
    this.resetFn(obj);
    this.pool.push(obj);
  }

  clear() {
    this.pool.length = 0;
  }
}
```

### 3.2 星空背景系统 (src/systems/StarField.js)
```javascript
class StarField {
  constructor(canvas) {
    this.canvas = canvas;
    this.stars = [];
    this.initStars();
  }

  initStars() {
    // 创建多层星星实现视差效果
    for (let i = 0; i < 100; i++) {
      this.stars.push({
        x: Math.random() * this.canvas.width,
        y: Math.random() * this.canvas.height,
        size: Math.random() * 2 + 0.5,
        speed: Math.random() * 50 + 20,
        layer: Math.floor(Math.random() * 3) // 0, 1, 2 三层
      });
    }
  }

  update(dt) {
    this.stars.forEach(star => {
      star.y += star.speed * (star.layer + 1) * dt;

      // 循环移动
      if (star.y > this.canvas.height) {
        star.y = 0;
        star.x = Math.random() * this.canvas.width;
      }
    });
  }

  render(ctx) {
    this.stars.forEach(star => {
      const alpha = 0.3 + star.layer * 0.3;
      ctx.fillStyle = `rgba(255, 255, 255, ${alpha})`;
      ctx.fillRect(star.x, star.y, star.size, star.size);
    });
  }
}
```

### 3.3 性能监控工具 (src/utils/Performance.js)
```javascript
class PerformanceMonitor {
  constructor() {
    this.metrics = {
      fps: [],
      frameTime: [],
      memory: [],
      entityCount: []
    };
    this.startTime = performance.now();
  }

  update(game) {
    const now = performance.now();

    // 记录FPS
    this.metrics.fps.push(game.fps);
    if (this.metrics.fps.length > 60) this.metrics.fps.shift();

    // 记录帧时间
    this.metrics.frameTime.push(game.deltaTime * 1000);
    if (this.metrics.frameTime.length > 60) this.metrics.frameTime.shift();

    // 记录实体数量
    this.metrics.entityCount.push(game.entities.length);
    if (this.metrics.entityCount.length > 60) this.metrics.entityCount.shift();

    // 内存使用（如果可用）
    if (performance.memory) {
      this.metrics.memory.push(performance.memory.usedJSHeapSize / 1024 / 1024);
      if (this.metrics.memory.length > 60) this.metrics.memory.shift();
    }
  }

  getReport() {
    return {
      avgFPS: this.metrics.fps.reduce((a, b) => a + b, 0) / this.metrics.fps.length,
      avgFrameTime: this.metrics.frameTime.reduce((a, b) => a + b, 0) / this.metrics.frameTime.length,
      maxEntities: Math.max(...this.metrics.entityCount),
      avgMemory: this.metrics.memory.length > 0 ? 
        this.metrics.memory.reduce((a, b) => a + b, 0) / this.metrics.memory.length : 0,
      uptime: (performance.now() - this.startTime) / 1000
    };
  }
}
```

## 四、测试与验证

### 4.1 单元测试 (tests/unit/Game.test.js)
```javascript
describe('Game Core', () => {
  let game;
  let canvas;

  beforeEach(() => {
    canvas = document.createElement('canvas');
    canvas.width = 800;
    canvas.height = 600;
    game = new Game(canvas);
  });

  test('should initialize correctly', () => {
    expect(game.canvas).toBe(canvas);
    expect(game.isRunning).toBe(false);
    expect(game.entities).toEqual([]);
  });

  test('should start game loop', () => {
    game.start();
    expect(game.isRunning).toBe(true);
  });
});
```

### 4.2 性能测试脚本 (tests/performance/performance.test.js)
```javascript
describe('Performance Tests', () => {
  test('should maintain 55+ FPS', async () => {
    const game = await setupGame();
    const fpsSamples = [];

    // 运行5秒收集FPS数据
    for (let i = 0; i < 300; i++) {
      await delay(16); // ~60fps
      fpsSamples.push(game.fps);
    }

    const avgFPS = fpsSamples.reduce((a, b) => a + b, 0) / fpsSamples.length;
    expect(avgFPS).toBeGreaterThanOrEqual(55);
  });

  test('should handle 100+ entities without lag', async () => {
    const game = await setupGame();

    // 添加100个实体
    for (let i = 0; i < 100; i++) {
      game.addEntity(new Enemy(Math.random() * 800, Math.random() * 600));
    }

    const startTime = performance.now();
    game.update(1/60);
    const updateTime = performance.now() - startTime;

    expect(updateTime).toBeLessThan(16); // 应该在16ms内完成
  });
});
```

### 4.3 浏览器兼容性验证
```javascript
// browser-compatibility.test.js
describe('Browser Compatibility', () => {
  const browsers = ['chrome', 'firefox', 'safari'];

  browsers.forEach(browser => {
    test(`should work in ${browser}`, async () => {
      const page = await browser_automation.launch(browser);
      await page.goto('http://localhost:3000');

      // 检查Canvas支持
      const canvasSupport = await page.evaluate(() => {
        const canvas = document.createElement('canvas');
        return !!canvas.getContext;
      });

      expect(canvasSupport).toBe(true);

      // 检查游戏启动
      const gameStarted = await page.evaluate(() => {
        return window.game && window.game.isRunning;
      });

      expect(gameStarted).toBe(true);

      await page.close();
    });
  });
});
```

